"""Adjusts the Android project generated by `flutter create` for this app:
permissions, background audio service, app name and launch colour."""
import glob
import re
import sys

M = 'android/app/src/main/AndroidManifest.xml'
m = open(M, encoding='utf-8').read()

if 'xmlns:tools' not in m:
    m = m.replace('<manifest xmlns:android="http://schemas.android.com/apk/res/android"',
                  '<manifest xmlns:android="http://schemas.android.com/apk/res/android"\n'
                  '    xmlns:tools="http://schemas.android.com/tools"', 1)

perms = ['INTERNET', 'WAKE_LOCK', 'FOREGROUND_SERVICE', 'FOREGROUND_SERVICE_MEDIA_PLAYBACK']
block = ''.join(f'    <uses-permission android:name="android.permission.{p}"/>\n' for p in perms)
m = m.replace('    <application', block + '    <application', 1)

m = re.sub(r'android:label="[^"]*"',
           'android:label="القرآن الكريم" android:usesCleartextTraffic="true"', m, count=1)

service = '''
        <service android:name="com.ryanheise.audioservice.AudioService"
            android:foregroundServiceType="mediaPlayback"
            android:exported="true" tools:ignore="Instantiatable">
            <intent-filter>
                <action android:name="android.media.browse.MediaBrowserService" />
            </intent-filter>
        </service>
        <receiver android:name="com.ryanheise.audioservice.MediaButtonReceiver"
            android:exported="true" tools:ignore="Instantiatable">
            <intent-filter>
                <action android:name="android.intent.action.MEDIA_BUTTON" />
            </intent-filter>
        </receiver>
    </application>'''
m = m.replace('    </application>', service.lstrip('\n'), 1)
open(M, 'w', encoding='utf-8').write(m)

for check in ['permission.INTERNET', 'FOREGROUND_SERVICE_MEDIA_PLAYBACK', 'usesCleartextTraffic',
              'audioservice.AudioService', 'MediaButtonReceiver', 'xmlns:tools']:
    if check not in m:
        sys.exit(f'manifest patch failed: {check}')

acts = glob.glob('android/app/src/main/kotlin/**/MainActivity.kt', recursive=True)
if len(acts) != 1:
    sys.exit(f'MainActivity.kt not found: {acts}')
a = open(acts[0], encoding='utf-8').read()
pkg = re.search(r'^package\s+(\S+)', a, re.M).group(1)
open(acts[0], 'w', encoding='utf-8').write(
    f'package {pkg}\n\n'
    'import com.ryanheise.audioservice.AudioServiceActivity\n\n'
    'class MainActivity : AudioServiceActivity()\n')

launch = ('<?xml version="1.0" encoding="utf-8"?>\n'
          '<layer-list xmlns:android="http://schemas.android.com/apk/res/android">\n'
          '    <item><color android:color="#1B3A6B" /></item>\n'
          '</layer-list>\n')
for f in glob.glob('android/app/src/main/res/drawable*/launch_background.xml'):
    open(f, 'w', encoding='utf-8').write(launch)

# App icon: legacy PNGs plus an adaptive icon (Android 8+) on a cream background.
import os
import shutil
RES = 'android/app/src/main/res'
for d in ['mdpi', 'hdpi', 'xhdpi', 'xxhdpi', 'xxxhdpi']:
    os.makedirs(f'{RES}/mipmap-{d}', exist_ok=True)
    shutil.copy(f'tool/icons/ic_launcher_{d}.png', f'{RES}/mipmap-{d}/ic_launcher.png')
    shutil.copy(f'tool/icons/ic_launcher_foreground_{d}.png', f'{RES}/mipmap-{d}/ic_launcher_foreground.png')
os.makedirs(f'{RES}/mipmap-anydpi-v26', exist_ok=True)
open(f'{RES}/mipmap-anydpi-v26/ic_launcher.xml', 'w').write(
    '<?xml version="1.0" encoding="utf-8"?>\n'
    '<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">\n'
    '    <background android:drawable="@color/ic_launcher_background"/>\n'
    '    <foreground android:drawable="@mipmap/ic_launcher_foreground"/>\n'
    '</adaptive-icon>\n')
os.makedirs(f'{RES}/values', exist_ok=True)
open(f'{RES}/values/ic_launcher_background.xml', 'w').write(
    '<?xml version="1.0" encoding="utf-8"?>\n'
    '<resources><color name="ic_launcher_background">#FBF6E9</color></resources>\n')

# ---- Google Play: target Android 16 (API 36) with build tools that support it
def sub_file(path, pattern, repl, label):
    t = open(path, encoding='utf-8').read()
    n = re.subn(pattern, repl, t)
    if n[1] == 0:
        sys.exit(f'{label}: pattern not found in {path}\n' + t[:1500])
    open(path, 'w', encoding='utf-8').write(n[0])

settings = next(f for f in ['android/settings.gradle', 'android/settings.gradle.kts'] if os.path.exists(f))
sub_file(settings, r'(id\s*\(?\s*"com\.android\.application"\s*\)?\s*version\s*)"[^"]+"', r'\g<1>"8.11.1"', 'AGP version')
sub_file(settings, r'(id\s*\(?\s*"org\.jetbrains\.kotlin\.android"\s*\)?\s*version\s*)"[^"]+"', r'\g<1>"2.1.0"', 'Kotlin version')
sub_file('android/gradle/wrapper/gradle-wrapper.properties', r'gradle-[0-9.]+-(all|bin)\.zip', 'gradle-8.14.3-all.zip', 'Gradle wrapper')
appg = next(f for f in ['android/app/build.gradle', 'android/app/build.gradle.kts'] if os.path.exists(f))
sub_file(appg, r'compileSdk\s*=\s*flutter\.compileSdkVersion', 'compileSdk = 36', 'compileSdk')
sub_file(appg, r'targetSdk\s*=\s*flutter\.targetSdkVersion', 'targetSdk = 36', 'targetSdk')

print('Android project patched:', acts[0])
